                bad.append((tname, i, f, 'MULTI SPAN %d' % len(spans)))

print('counts:', counts)
print('individuals:', len({r['individual_label_in_paper']['value'] for r in data['tables']['individuals']}))
print('problems:', len(bad))
for b in bad:
